private fun glyph(name: String, path: String, width: Float = 24f, height: Float = 24f): ImageVector =
    ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = (24f * height / width).dp, viewportWidth = width, viewportHeight = height)
        .addPath(pathData = addPathNodes(path), fill = SolidColor(Color.Black))
        .build()
